package com.hbm.client.solarboiler;
import com.hbm.client.model.*;import com.hbm.machine.solarboiler.SolarBoilerContent;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.*;
/** Actual ItemRenderBase plus boilerGUI-2.5/3.25,mirrorGUI-3/8 and mirror45degree arm pivot. */
public final class SolarBoilerItemRenderer extends BlockEntityWithoutLevelRenderer {
 public SolarBoilerItemRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}
 @Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack pose,MultiBufferSource buffers,int light,int overlay){boolean mirror=stack.is(SolarBoilerContent.MIRROR_ITEM.get());pose.pushPose();if(LegacyItemTransforms.isHeld(context))LegacyItemTransforms.held(pose,context);else pose.translate(.5,.5,.5);if(context==ItemDisplayContext.GUI){pose.scale(1F/16,-1F/16,1F/16);pose.translate(0,2,0);pose.mulPose(Axis.XP.rotationDegrees(-30));pose.mulPose(Axis.YP.rotationDegrees(45));pose.scale(-1,-1,-1);pose.translate(0,mirror?-3:-2.5,0);float scale=mirror?8:3.25F;pose.scale(scale,scale,scale);}else{boolean entity=context==ItemDisplayContext.GROUND||context==ItemDisplayContext.FIXED||context==ItemDisplayContext.NONE;if(entity)pose.scale(1.5F,1.5F,1.5F);else pose.translate(.5,.25,0);pose.scale(.25F,.25F,.25F);if(context!=ItemDisplayContext.THIRD_PERSON_LEFT_HAND&&context!=ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)pose.mulPose(Axis.YP.rotationDegrees(90));}if(!mirror)SolarBoilerRenderer.base(pose,buffers,light,overlay);else{var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/machines/solar_mirror.obj"));var consumer=buffers.getBuffer(RenderType.entityCutout(ResourceLocation.parse("hbm:textures/models/machines/solar_mirror.png")));LegacyObjRenderer.render(mesh,pose,consumer,light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR_FLAT,WavefrontMesh.legacyPart("Base"));pose.translate(0,1,0);pose.mulPose(Axis.ZN.rotationDegrees(45));pose.translate(0,-1,0);LegacyObjRenderer.render(mesh,pose,consumer,light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR_FLAT,WavefrontMesh.legacyPart("Mirror"));}pose.popPose();}
}
